function initDraggableInfiniteGSAPSlider() {
  const wrapper = nextPage.querySelector('[data-slider="list"]');
  if (!wrapper) return;

  const slides = gsap.utils.toArray(nextPage.querySelectorAll('[data-slider="slide"]'));
  const nextButton = nextPage.querySelector('[data-slider-button="next"]');
  const prevButton = nextPage.querySelector('[data-slider-button="prev"]');

  const totalElement = nextPage.querySelector('[data-slide-count="total"]');
  const stepElement = nextPage.querySelector('[data-slide-count="step"]');
  const stepsParent = stepElement?.parentElement;

  let activeElement;
  const totalSlides = slides.length;

  // Total
  if (totalElement) totalElement.textContent = totalSlides < 10 ? `0${totalSlides}` : totalSlides;

  // Steps
  if (stepElement) {
    stepElement.textContent = "01";
  }

  let currentEl = null;
  let currentIndex = 0;

  function applyActive(el, index, animateNumbers = true) {
    if (activeElement) activeElement.classList.remove('active');
    el.classList.add('active');
    activeElement = el;

    if (stepElement) {
      if (animateNumbers) {
        gsap.to(stepElement, {
          opacity: 0,
          y: -10,
          duration: 0.15,
          onComplete: () => {
            stepElement.textContent = index + 1 < 10 ? `0${index + 1}` : (index + 1);
            gsap.fromTo(stepElement, { y: 10 }, { opacity: 1, y: 0, duration: 0.2, ease: "power2.out" });
          }
        });
      } else {
        stepElement.textContent = index + 1 < 10 ? `0${index + 1}` : (index + 1);
        gsap.set(stepElement, { opacity: 1, y: 0 });
      }
    }
  }

  const loop = horizontalLoop(slides, {
    paused: true,
    draggable: true,
    center: false,
    onChange: (element, index) => {
      currentEl = element;
      currentIndex = index;
      applyActive(element, index, true);
    }
  });

  function goToIndex(i) {
    loop.toIndex(i, { ease: "power3", duration: 0.8 });
    let targetIndex = gsap.utils.wrap(0, totalSlides, i);
    currentIndex = targetIndex;
    if (slides[targetIndex]) {
      applyActive(slides[targetIndex], targetIndex, true);
    }
  }

  slides.forEach((slide, i) => {
    slide.addEventListener("click", () => {
      if (slide.classList.contains("active")) return;
      goToIndex(i);
    });
  });

  nextButton?.addEventListener("click", () => goToIndex(currentIndex + 1));
  prevButton?.addEventListener("click", () => goToIndex(currentIndex - 1));

  if (!currentEl && slides[0]) {
    currentEl = slides[0];
    currentIndex = 0;
    applyActive(currentEl, currentIndex, false);
  }
}

